import pandas as pdimport tkinter as tkfrom tkinter import filedialog, messageboxdef main():    root = tk.Tk()    root.withdraw()    messagebox.showwarning("Important", "Please select only .xls Files")    file_path = filedialog.askopenfilename(filetypes=[('Excel', '*.xls')])    if not file_path:        messagebox.showerror("Error", "No file selected.")        return    try:        df = pd.read_excel(file_path, sheet_name='Sheet')    except Exception as e:        messagebox.showerror("Error", f"Failed to read Excel file:\n{e}")        return    # Keywords for different expense types    food_companies = ['KAUFLAND', 'BILLA', 'LIDL', 'BOLERO', 'ANET', 'LIDAL', 'MINIMARKET']    petrol_companies = ['BI OIL', 'DEGA', 'LUKOIL', 'EKO', "SHELL"]    monthly_tax_keywords = ['SOFIYSKA VODA', 'OVERGAS', 'PB PERSONAL', 'YETTEL', 'ELEKTROHOLD']    # Totals    revolut_expenses = withdraw_expenses = gas_expenses = food_expenses = 0.0    other_expenses = monthly_tax_expenses = 0.0    # Entries for printing    revolut_entries, gas_entries, other_entries, monthly_tax_entries, withdraw_entries = [], [], [], [], []    # To store city expenses    city_expenses = {}    income = 0    for i in range(9, len(df)):        try:            amount = df.iloc[i, 3]            payment_method = df.iloc[i, 5]            description = df.iloc[i, 7]            credit_amount = df.iloc[i, 4]            if pd.isna(amount) and not pd.isna(credit_amount):                income += float(credit_amount)                continue            elif pd.isna(amount):                continue            amount = float(amount)            desc_str = str(description).upper() if isinstance(description, str) else ""            pay_str = str(payment_method).upper() if isinstance(payment_method, str) else ""            # Try to extract city from description (assuming city is at the end of the description)            # Looking for city names like "PLEVEN", "SOFIA", etc.            city = None            # Normalized city name mapping            city_variants = {                'SOFIYA': 'SOFIA',                'SOFIA': 'SOFIA',                'PLEVEN': 'PLEVEN',                'Sofia': 'SOFIA',                'Pleven': 'PLEVEN',                'VARNA': 'VARNA',                'BURGAS': 'BURGAS',                'PLOVDIV': 'PLOVDIV',                'RUSE': 'RUSE',                'STARA ZAGORA': 'STARA ZAGORA',                'SEVLIEVO': 'SEVLIEVO',            }            for variant, normalized in city_variants.items():                if variant in desc_str:                    city = normalized                    break            # Classification logic            if any(kw in desc_str for kw in monthly_tax_keywords):                monthly_tax_expenses += amount                monthly_tax_entries.append((amount, description))            elif 'REVOLUT' in desc_str or 'REVOLUT' in pay_str:                revolut_expenses += amount                revolut_entries.append((amount, description))            elif 'ATM' in pay_str:                withdraw_expenses += amount                withdraw_entries.append((amount, description))                if city:                    # Add to city expenses if city is found                    if city not in city_expenses:                        city_expenses[city] = 0.0                    city_expenses[city] += amount                else:                    # If no city found, add to Sofia expenses                    city_expenses['SOFIA'] += amount            elif any(comp in desc_str for comp in petrol_companies):                gas_expenses += amount                gas_entries.append((amount, description))            elif any(comp in desc_str for comp in food_companies):                food_expenses += amount            else:                other_expenses += amount                other_entries.append((amount, description))            # Add amount to city expenses if city is found (for other types of expenses)            if city and 'ATM' not in pay_str:                if city not in city_expenses:                    city_expenses[city] = 0.0                city_expenses[city] += amount        except Exception as e:            print(f"Error processing row {i}: {e}")    expenses = sum([revolut_expenses, withdraw_expenses, gas_expenses, food_expenses, other_expenses, monthly_tax_expenses])    total_net = income - expenses    # === PRINT SECTION ===    output = ""    # Append all the details into the output string    output += 'REVOLUT EXPENSES:\n'    for amt, desc in revolut_entries:        output += f"{amt:.2f} EUR -> {desc}\n"    output += '\nGAS EXPENSES:\n'    for amt, desc in gas_entries:        output += f"{amt:.2f} EUR -> {desc}\n"    output += '\nMONTHLY TAXES:\n'    for amt, desc in monthly_tax_entries:        output += f"{amt:.2f} EUR -> {desc}\n"    output += '\nWITHDRAW EXPENSES:\n'  # Added section for withdraw expenses    for amt, desc in withdraw_entries:        output += f"{amt:.2f} EUR -> {desc}\n"  # Printing each withdraw expense    output += '\nOTHER EXPENSES:\n'    for amt, desc in other_entries:        output += f"{amt:.2f} EUR -> {desc}\n"    output += "\nTOTALS:\n"    output += f'Gas Expenses: {gas_expenses:.2f} EUR\n'    output += f'Food Expenses: {food_expenses:.2f} EUR\n'    output += f'Withdraw Expenses: {withdraw_expenses:.2f} EUR\n'    output += f'Revolut Expenses: {revolut_expenses:.2f} EUR\n'    output += f'Monthly Tax Expenses: {monthly_tax_expenses:.2f} EUR\n'    output += f'Other Expenses: {other_expenses:.2f} EUR\n\n'    output += f'Total Expenses: {expenses:.2f} EUR\n'    output += f'NET: {total_net:.2f} EUR\n'    # === CITY EXPENSES ===    output += "\nEXPENSES PER CITY:\n"    for city, total in city_expenses.items():        output += f"{city}: {total:.2f} EUR\n"    # Print the result to console    # print(output)    # print(income)    # print(expenses)    # print(total_net)    # Ask the user if they want to save the output to a file    save_to_file = messagebox.askyesno("Save to file", "Do you want to save the output to a text file?")    if save_to_file:        # Let the user choose the file path to save the text file        file_save_path = filedialog.asksaveasfilename(defaultextension=".txt", filetypes=[("Text files", "*.txt")])        if file_save_path:            try:                with open(file_save_path, 'w', encoding='utf-8') as file:                    file.write(output)                messagebox.showinfo("Success", f"File saved successfully to {file_save_path}")            except Exception as e:                messagebox.showerror("Error", f"Failed to save file: {e}")if __name__ == "__main__":    main()